<template><ForgeDialog title="Keyboard inspector" description="Press any key while this panel is focused to inspect its event properties." eyebrow="WORKSPACE / CODE" @close="emit('close')"><div class="key-panel" tabindex="0" @keydown.prevent="capture"><div class="key-hero">{{ event?.key || 'Press a key' }}</div><p class="website-help">Click the panel, then press a key. Modifier combinations are captured too.</p><div class="key-grid"><div v-for="field in fields" :key="field.label"><span>{{ field.label }}</span><code>{{ field.value || '—' }}</code></div></div></div></ForgeDialog></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
const emit=defineEmits<{close:[]}>(); const event=ref<KeyboardEvent>(); const capture=(value:KeyboardEvent)=>{event.value=value}; const fields=computed(()=>{const e=event.value;return e?[{label:'Key',value:e.key},{label:'Code',value:e.code},{label:'Key code',value:String(e.keyCode)},{label:'Location',value:String(e.location)},{label:'Modifiers',value:[e.metaKey&&'Meta',e.ctrlKey&&'Ctrl',e.altKey&&'Alt',e.shiftKey&&'Shift'].filter(Boolean).join(' + ')}]:[]})
</script>
<style scoped>.key-panel{display:grid;gap:16px;min-height:350px;padding:14px;border:1px dashed var(--pqt-border-strong);border-radius:9px;outline:none}.key-panel:focus{border-color:var(--pqt-accent)}.key-hero{display:grid;place-items:center;min-height:120px;border-radius:8px;background:var(--pqt-canvas);color:var(--pqt-accent);font-size:30px;font-weight:700}.key-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.key-grid div{display:grid;gap:4px;padding:9px;border:1px solid var(--pqt-border);border-radius:6px}.key-grid span{color:var(--pqt-text-muted);font-size:10px;text-transform:uppercase}.key-grid code{color:var(--pqt-text);font:12px var(--pqt-font-mono)}</style>
